mapper.select:
SELECT m.message_id AS messageId, m.conversation_id AS conversationId, m.sender_user_id AS senderUserId, u.nick_name AS senderName, u.avatar, m.client_message_id AS clientMessageId, m.message_type AS messageType, m.content, m.create_time AS createTime FROM chat_message m JOIN chat_conversation c ON c.conversation_id = m.conversation_id AND c.status = '0' JOIN chat_conversation_member viewer ON viewer.conversation_id = m.conversation_id AND viewer.user_id = #{userId} AND viewer.left_at IS NULL JOIN sys_user u ON u.user_id = m.sender_user_id WHERE m.conversation_id = #{conversationId} AND m.deleted_flag = '0'
AND m.message_id > #{afterMessageId}
AND m.message_id < #{beforeMessageId}
ORDER BY m.message_id ASC ORDER BY m.message_id DESC
LIMIT #{limit}
